CREATE TYPE public.app_role AS ENUM ('admin','engineer','reviewer','viewer');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', organisation text NOT NULL DEFAULT '');
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,organisation) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name',''),coalesce(NEW.raw_user_meta_data->>'organisation','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'engineer'); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_account_profile() FROM PUBLIC;
CREATE TRIGGER account_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, vessel text NOT NULL, vessel_type text NOT NULL, class_society text NOT NULL, flag text NOT NULL, length_m numeric NOT NULL CHECK(length_m>0), lead_engineer text NOT NULL, version text NOT NULL DEFAULT 'Rev A', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.projects TO authenticated;
GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY project_read ON public.projects FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY project_create ON public.projects FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND (public.has_role(auth.uid(),'engineer') OR public.has_role(auth.uid(),'admin')));
CREATE INDEX projects_owner_idx ON public.projects(user_id);
CREATE TABLE public.design_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, storage_path text UNIQUE NOT NULL, size_bytes bigint NOT NULL, revision text NOT NULL DEFAULT 'A', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.design_documents TO authenticated;
GRANT ALL ON public.design_documents TO service_role;
ALTER TABLE public.design_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY document_read ON public.design_documents FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
CREATE POLICY document_create ON public.design_documents FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND split_part(storage_path,'/',1)=auth.uid()::text AND split_part(storage_path,'/',2)=project_id::text AND EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()) AND (public.has_role(auth.uid(),'engineer') OR public.has_role(auth.uid(),'admin')));
CREATE INDEX documents_owner_idx ON public.design_documents(user_id,project_id);
CREATE POLICY design_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='design-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY design_file_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='design-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.projects p WHERE p.id::text=(storage.foldername(name))[2] AND p.user_id=auth.uid()) AND (public.has_role(auth.uid(),'engineer') OR public.has_role(auth.uid(),'admin')));
CREATE POLICY design_file_cleanup ON storage.objects FOR DELETE TO authenticated USING(bucket_id='design-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND (public.has_role(auth.uid(),'engineer') OR public.has_role(auth.uid(),'admin')));